import * as THREE from 'three';
// Exposure is a viewing preference, not a photometric lux measurement.
export function lightSubstation134(scene){const lights=[];const ambient=new THREE.HemisphereLight('#f3f4ef','#505b58',.48);scene.add(ambient);lights.push(ambient);for(const [x,z]of[[-5,0],[0,-1],[5,0]]){const l=new THREE.PointLight('#f2f4ee',26,14,2);l.position.set(x,3.45,z);l.castShadow=false;scene.add(l);lights.push(l);}return lights;}
export function entryCamera134(camera,controls){camera.fov=68;camera.position.set(0,1.68,-4.25);controls.target.set(0,1.68,2);camera.updateProjectionMatrix();controls.update();}
export function inspectionCamera134(camera,controls,group){group.updateWorldMatrix(true,true);const b=new THREE.Box3().setFromObject(group),center=b.getCenter(new THREE.Vector3()),size=b.getSize(new THREE.Vector3());camera.fov=42;const half=Math.max(size.y,size.x/Math.max(.3,camera.aspect))/2,distance=Math.max(1.6,half/Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*1.28+size.z/2);controls.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(.025,.035,-1).normalize().multiplyScalar(distance));camera.updateProjectionMatrix();controls.update();}
